From 1ecfaa3b9dcf6ce9b2c42fc09e0210f0f1652c1f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Wed, 25 Nov 2026 22:40:25 +0100
Subject: [PATCH] applets/cameraindicator: add a switch to allow or block
 camera access

The camera indicator had no way to refuse the camera to apps. Its new
switch sets the portal's disable-camera lockdown, and the indicator
stays visible while access is blocked so that it can be turned back on.

BUG: 447034
---
 .../qml/FullRepresentation.qml                | 12 ++++++
 applets/cameraindicator/qml/main.qml          | 39 ++++++++++++++++++-
 portal-configuration/kde-portals.conf         |  1 +
 3 files changed, 51 insertions(+), 1 deletion(-)

diff --git a/applets/cameraindicator/qml/FullRepresentation.qml b/applets/cameraindicator/qml/FullRepresentation.qml
index cedaf64775..248e3454e2 100644
--- a/applets/cameraindicator/qml/FullRepresentation.qml
+++ b/applets/cameraindicator/qml/FullRepresentation.qml
@@ -18,6 +18,18 @@ PlasmaComponents.Page {
     implicitWidth: root.switchWidth
     implicitHeight: root.switchHeight

+    header: PlasmaExtras.PlasmoidHeading {
+        visible: root.toggleCameraAction.visible
+
+        contentItem: PlasmaComponents.Switch {
+            text: root.toggleCameraAction.text
+            icon.name: root.toggleCameraAction.icon.name
+            checked: root.toggleCameraAction.checked
+            focus: root.expanded
+            onToggled: root.toggleCameraAction.trigger()
+        }
+    }
+
     PlasmaExtras.PlaceholderMessage {
         anchors.centerIn: parent

diff --git a/applets/cameraindicator/qml/main.qml b/applets/cameraindicator/qml/main.qml
index f29ef4f4ba..afea846f18 100644
--- a/applets/cameraindicator/qml/main.qml
+++ b/applets/cameraindicator/qml/main.qml
@@ -12,6 +12,7 @@ import org.kde.plasma.plasmoid
 import org.kde.plasma.core as PlasmaCore
 import org.kde.kirigami as Kirigami
 import org.kde.pipewire.monitor as Monitor
+import org.kde.plasma.workspace.dbus as DBus

 PlasmoidItem {
     id: root
@@ -20,11 +21,15 @@ PlasmoidItem {
     switchHeight: Kirigami.Units.gridUnit * 12

     property bool inEmbeddedContainment: Plasmoid.containment.containmentType === PlasmaCore.Containment.CustomEmbedded
+    readonly property bool cameraBlocked: Boolean(lockdown.properties["disable-camera"])
+    readonly property alias toggleCameraAction: toggleCameraAction

     toolTipSubText: if (!monitor.detectionAvailable) {
         return i18nc("@info:tooltip", "Camera indicator is unavailable");
     } else if (monitor.runningCount) {
         return i18ncp("@info:tooltip", "A camera is in use", "%1 cameras are in use", monitor.runningCount);
+    } else if (cameraBlocked) {
+        return i18nc("@info:tooltip", "Camera access is blocked");
     } else {
         return i18nc("@info:tooltip", "No camera is in use");
     }
@@ -38,12 +43,44 @@ PlasmoidItem {
     } else {
         return "camera-off-symbolic";
     }
-    Plasmoid.status: (monitor.idleCount > 0 || monitor.runningCount > 0) ? PlasmaCore.Types.ActiveStatus : inEmbeddedContainment ?  PlasmaCore.Types.HiddenStatus : PlasmaCore.Types.PassiveStatus
+    Plasmoid.status: (monitor.idleCount > 0 || monitor.runningCount > 0 || cameraBlocked) ? PlasmaCore.Types.ActiveStatus : inEmbeddedContainment ?  PlasmaCore.Types.HiddenStatus : PlasmaCore.Types.PassiveStatus

     Monitor.MediaMonitor {
         id: monitor
         role: Monitor.MediaRole.Camera
     }

+    // Apps asking for the camera through the desktop portal are refused while "disable-camera" is set
+    DBus.Properties {
+        id: lockdown
+        busType: DBus.BusType.Session
+        service: "org.freedesktop.impl.portal.desktop.kde.lockdown"
+        path: "/org/freedesktop/portal/desktop"
+        iface: "org.freedesktop.impl.portal.Lockdown"
+    }
+
+    DBus.DBusServiceWatcher {
+        busType: DBus.BusType.Session
+        watchedService: lockdown.service
+        onRegisteredChanged: if (registered) {
+            lockdown.updateAll();
+        }
+    }
+
+    Plasmoid.contextualActions: [
+        PlasmaCore.Action {
+            id: toggleCameraAction
+            text: i18nc("@option:check", "Allow camera access")
+            icon.name: "camera-web-symbolic"
+            priority: PlasmaCore.Action.LowPriority
+            checkable: true
+            checked: !root.cameraBlocked
+            visible: lockdown.properties["disable-camera"] !== undefined
+            onTriggered: checked => {
+                lockdown.properties["disable-camera"] = !checked;
+            }
+        }
+    ]
+
     fullRepresentation: FullRepresentation { }
 }
diff --git a/portal-configuration/kde-portals.conf b/portal-configuration/kde-portals.conf
index c618e2638b..14cc4322be 100644
--- a/portal-configuration/kde-portals.conf
+++ b/portal-configuration/kde-portals.conf
@@ -3,3 +3,4 @@ default=kde
 org.freedesktop.impl.portal.Settings=kde;gtk;
 org.freedesktop.impl.portal.Secret=kwallet
 org.freedesktop.impl.portal.Notification=plasmanotify
+org.freedesktop.impl.portal.Lockdown=kde-lockdown
