+install(FILES kde.portal kde-lockdown.portal DESTINATION ${KDE_INSTALL_DATADIR}/xdg-desktop-portal/portals)
+install(FILES ${CMAKE_CURRENT_BINARY_DIR}/org.freedesktop.impl.portal.desktop.kde.service ${CMAKE_CURRENT_BINARY_DIR}/org.freedesktop.impl.portal.desktop.kde.lockdown.service DESTINATION ${KDE_INSTALL_DBUSSERVICEDIR})
 install(FILES ${CMAKE_CURRENT_BINARY_DIR}/org.freedesktop.impl.portal.desktop.kde.desktop DESTINATION ${KDE_INSTALL_APPDIR})

 ecm_install_configured_files(INPUT plasma-xdg-desktop-portal-kde.service.in @ONLY
