diff --git a/src/lockdown.cpp b/src/lockdown.cpp
new file mode 100644
index 00000000..d86cdd5d
--- /dev/null
+++ b/src/lockdown.cpp
@@ -0,0 +1,105 @@
+/*
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+*/
+
+#include "lockdown.h"
+#include "desktopportal_debug.h"
+
+#include <QDBusConnectionInterface>
+#include <QDBusMessage>
+#include <QDBusVariant>
+
+#include <KSharedConfig>
+
+using namespace Qt::StringLiterals;
+
+static constexpr QLatin1StringView s_interface("org.freedesktop.impl.portal.Lockdown");
+static constexpr QLatin1StringView s_propertiesInterface("org.freedesktop.DBus.Properties");
+static constexpr QLatin1StringView s_path("/org/freedesktop/portal/desktop");
+static const QStringList s_properties = {
+    u"disable-printing"_s,
+    u"disable-save-to-disk"_s,
+    u"disable-application-handlers"_s,
+    u"disable-location"_s,
+    u"disable-camera"_s,
+    u"disable-microphone"_s,
+    u"disable-sound-output"_s,
+};
+
+LockdownPortal::LockdownPortal(QObject *parent)
+    : QDBusVirtualObject(parent)
+    , m_bus(QDBusConnection::connectToBus(QDBusConnection::SessionBus, u"xdg-desktop-portal-kde-lockdown"_s))
+    , m_config(KSharedConfig::openConfig()->group(u"Lockdown"_s))
+{
+    if (!m_bus.registerVirtualObject(s_path, this)) {
+        qCWarning(XdgDesktopPortalKdeDesktopPortal) << "Failed to register the lockdown portal object";
+        return;
+    }
+    if (!m_bus.interface()->registerService(u"org.freedesktop.impl.portal.desktop.kde.lockdown"_s,
+                                            QDBusConnectionInterface::ReplaceExistingService,
+                                            QDBusConnectionInterface::AllowReplacement)) {
+        qCWarning(XdgDesktopPortalKdeDesktopPortal) << "Failed to register the lockdown portal service";
+    }
+}
+
+QString LockdownPortal::introspect(const QString &path) const
+{
+    Q_UNUSED(path)
+    QString xml = u"  <interface name=\"%1\">\n"_s.arg(s_interface);
+    for (const QString &property : s_properties) {
+        xml += u"    <property name=\"%1\" type=\"b\" access=\"readwrite\"/>\n"_s.arg(property);
+    }
+    xml += u"  </interface>\n"_s;
+    return xml;
+}
+
+QVariantMap LockdownPortal::properties() const
+{
+    QVariantMap properties;
+    for (const QString &property : s_properties) {
+        properties.insert(property, m_config.readEntry(property, false));
+    }
+    return properties;
+}
+
+bool LockdownPortal::handleMessage(const QDBusMessage &message, const QDBusConnection &connection)
+{
+    const QVariantList arguments = message.arguments();
+    if (message.path() != s_path || message.interface() != s_propertiesInterface || arguments.value(0).toString() != s_interface) {
+        return false;
+    }
+
+    const QString property = arguments.value(1).toString();
+    if (message.member() == "GetAll"_L1) {
+        connection.send(message.createReply(QVariant::fromValue(properties())));
+        return true;
+    }
+    if (!s_properties.contains(property)) {
+        connection.send(message.createErrorReply(QDBusError::UnknownProperty, u"No such property %1"_s.arg(property)));
+        return true;
+    }
+    if (message.member() == "Get"_L1) {
+        connection.send(message.createReply(QVariant::fromValue(QDBusVariant(m_config.readEntry(property, false)))));
+        return true;
+    }
+    if (message.member() == "Set"_L1) {
+        const QVariant value = arguments.value(2).value<QDBusVariant>().variant();
+        if (value.metaType() != QMetaType::fromType<bool>()) {
+            connection.send(message.createErrorReply(QDBusError::InvalidArgs, u"%1 must be a boolean"_s.arg(property)));
+            return true;
+        }
+        connection.send(message.createReply());
+        if (m_config.readEntry(property, false) != value.toBool()) {
+            m_config.writeEntry(property, value.toBool());
+            m_config.sync();
+            QDBusMessage changed = QDBusMessage::createSignal(s_path, s_propertiesInterface, u"PropertiesChanged"_s);
+            changed << QString(s_interface) << QVariantMap{{property, value}} << QStringList();
+            m_bus.send(changed);
+        }
+        return true;
+    }
+    return false;
+}
+
+#include "moc_lockdown.cpp"
diff --git a/src/lockdown.h b/src/lockdown.h
new file mode 100644
index 00000000..7bb6e2f9
--- /dev/null
+++ b/src/lockdown.h
@@ -0,0 +1,29 @@
+/*
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+*/
+
+#pragma once
+
+#include <QDBusConnection>
+#include <QDBusVirtualObject>
+
+#include <KConfigGroup>
+
+// The Lockdown properties have dashes in their names, which QDBusAbstractAdaptor can't export,
+// so they are served by hand on a connection of their own.
+class LockdownPortal : public QDBusVirtualObject
+{
+    Q_OBJECT
+public:
+    explicit LockdownPortal(QObject *parent);
+
+    QString introspect(const QString &path) const override;
+    bool handleMessage(const QDBusMessage &message, const QDBusConnection &connection) override;
+
+private:
+    QVariantMap properties() const;
+
+    QDBusConnection m_bus;
+    KConfigGroup m_config;
+};
-- 
2.53.0
